package com.rezoxnemesis.videostudio;

import android.content.Context;
import android.graphics.Bitmap;
import android.graphics.Canvas;
import org.json.JSONArray;
import org.json.JSONObject;
import java.nio.charset.StandardCharsets;

/** Worker bridge between immutable paint files and the atomic sketch revision lane. */
public final class SketchPaintOps {
    private SketchPaintOps() {}
    public static boolean containsPaint(JSONArray operations)throws Exception {
        for(int i=0;i<operations.length();i++){String type=operations.getJSONObject(i).optString("type");if("add_paint_cel".equals(type)||"paint_stroke".equals(type))return true;}return false;
    }
    public static boolean containsDependencyCopies(JSONArray operations)throws Exception {
        for(int i=0;i<operations.length();i++){String type=operations.getJSONObject(i).optString("type");if("duplicate_cel".equals(type)||"clear_cel".equals(type))return true;}return false;
    }
    /** Hash-bound paint pointers are generated by native authoring, never supplied through vector edits. */
    public static void validatePublicOperations(JSONArray operations)throws Exception {
        for(int i=0;i<operations.length();i++){JSONObject operation=operations.getJSONObject(i);String type=operation.optString("type");
            if("add_object".equals(type))rejectPaintPointer(operation.getJSONObject("object"));
            if("update_object".equals(type)){JSONObject patch=operation.getJSONObject("patch");if(patch.has("paint")||"paint".equals(patch.optString("kind")))throw SketchDocument.bad("Create paint cels with add_paint_cel and author pixels with paint_stroke");}
            if("add_layer".equals(type)){JSONObject layer=operation.getJSONObject("layer");if(layer.has("objects")){JSONArray objects=layer.getJSONArray("objects");for(int j=0;j<objects.length();j++)rejectPaintPointer(objects.getJSONObject(j));}}
        }
    }
    private static void rejectPaintPointer(JSONObject object){if(object.has("paint")||"paint".equals(object.optString("kind")))throw SketchDocument.bad("Create paint cels with add_paint_cel and author pixels with paint_stroke");}

    public static JSONObject executeEdit(Context context,SketchProjectStore sketches,String id,String operationId,long revision,String fingerprint,JSONArray operations)throws Exception {
        SketchDrawingPolicy.requireOperations(sketches.activeDrawingSession(id),operations);
        SketchProjectStore.MutationPreflight admitted=sketches.preflightMutation(id,operationId,revision,fingerprint,operations);if(admitted.receipt!=null)return admitted.receipt;
        for(int i=0;i<operations.length();i++)SketchLayeredDrawing.requireOperation(admitted.document,operations.getJSONObject(i));
        JSONObject next=SketchDocument.copy(admitted.document);JSONArray visual=new JSONArray(),changes=new JSONArray();
        SketchPaintStore assets=null;try{
            for(int i=0;i<operations.length();i++){
                JSONObject operation=operations.getJSONObject(i);String type=operation.getString("type");
                if("add_paint_cel".equals(type)){
                    SketchDocument.fields(operation,"type,layerId,objectId,frame,exposure");String layerId=SketchDocument.id(operation,"layerId"),objectId=SketchDocument.id(operation,"objectId");JSONObject layer=SketchDocument.layer(next,layerId);SketchEditOps.requireUnlocked(layer);
                    int frame=operation.has("frame")?(int)SketchDocument.integer(operation,"frame",0,next.getInt("frameCount")-1):0;
                    int exposure=operation.has("exposure")?(int)SketchDocument.integer(operation,"exposure",1,next.getInt("frameCount")-frame):1;
                    String zeros=new String(new char[64]).replace('\0','0');JSONObject placeholder=new JSONObject().put("file",zeros+".json").put("sha256",zeros).put("width",next.getInt("width")).put("height",next.getInt("height")).put("tileSize",SketchPaintStore.TILE_SIZE);
                    JSONObject cel=SketchEditOps.completeObject(new JSONObject().put("id",objectId).put("kind","paint").put("frame",frame).put("exposure",exposure).put("bounds",new JSONObject().put("x",0).put("y",0).put("width",1).put("height",1)).put("paint",placeholder));
                    layer.getJSONArray("objects").put(cel);SketchLayeredDrawing.afterOperation(next);SketchDocument.validate(next);if(assets==null)assets=new SketchPaintStore(context,id);JSONObject descriptor=assets.empty(next.getInt("width"),next.getInt("height"));cel.put("paint",SketchDocument.copy(descriptor));
                    visual.put(new JSONObject().put("type","add_object").put("layerId",layerId).put("object",SketchDocument.copy(cel)));changes.put(new JSONObject().put("objectId",objectId).put("snapshotSha256",descriptor.getString("sha256")).put("dirtyTileCount",0));
                }else if("paint_stroke".equals(type)){
                    // Public requests cannot inject native-owned source or snapshot pins.
                    SketchDocument.fields(operation,"type,objectId,strokeId,points,brush,frameIndex,alphaLock,clip,cloneSource");
                    if(assets==null)assets=new SketchPaintStore(context,id);SketchPaintStore.PreparedChange prepared=assets.prepare(next,operation);applyPreparedStroke(next,prepared.visualOperation);SketchLayeredDrawing.afterOperation(next);SketchDocument.validate(next);
                    visual.put(SketchDocument.copy(prepared.visualOperation));changes.put(new JSONObject().put("objectId",SketchDocument.id(operation,"objectId")).put("snapshotSha256",prepared.descriptor.getString("sha256")).put("strokeSha256",prepared.strokeSha256).put("dirtyTileCount",prepared.dirtyTileCount));
                }else if("trace_reference".equals(type)){
                    JSONObject layer=SketchDocument.layer(next,operation.getString("layerId"));int before=layer.getJSONArray("objects").length();SketchReferenceTrace.apply(sketches,next,operation);SketchLayeredDrawing.afterOperation(next);SketchDocument.validate(next);for(int k=before;k<layer.getJSONArray("objects").length();k++)visual.put(new JSONObject().put("type","add_object").put("layerId",layer.getString("id")).put("object",SketchDocument.copy(layer.getJSONArray("objects").getJSONObject(k))));
                }else if("symmetry_stroke".equals(type)){
                    JSONArray expanded=SketchSymmetry.apply(next,operation);for(int k=0;k<expanded.length();k++)visual.put(SketchDocument.copy(expanded.getJSONObject(k)));
                }else{
                    JSONObject resolved=SketchSpeechAssets.expand(context,next,operation);
                    SketchEditOps.apply(next,resolved);visual.put(SketchDocument.copy(resolved));
                }
            }
        }finally{if(assets!=null)assets.close();}
        JSONObject preparedDocument=SketchDocument.copy(next);JSONObject details=new JSONObject().put("paintChanges",changes);
        java.util.HashSet<String> priorObjects=new java.util.HashSet<>();JSONArray originalLayers=admitted.document.getJSONArray("layers");for(int i=0;i<originalLayers.length();i++){JSONArray objects=originalLayers.getJSONObject(i).getJSONArray("objects");for(int j=0;j<objects.length();j++)priorObjects.add(objects.getJSONObject(j).getString("id"));}
        JSONObject seedDrawing=SketchDocument.copy(next);JSONArray seedLayers=seedDrawing.getJSONArray("layers");for(int i=0;i<seedLayers.length();i++){JSONArray objects=seedLayers.getJSONObject(i).getJSONArray("objects");for(int j=objects.length()-1;j>=0;j--){JSONObject object=objects.getJSONObject(j);if(!"paint".equals(object.getString("kind"))||priorObjects.contains(object.getString("id")))objects.remove(j);}}
        // Final admission rechecks revision and receipt. A conflict leaves only harmless
        // immutable orphan files and produces no history, accepted stroke or live event.
        return sketches.mutatePrepared(id,operationId,revision,fingerprint,ignored->{
            SketchDrawingPolicy.requireOperations(sketches.activeDrawingSession(id),operations);
            return SketchDocument.copy(preparedDocument);
        },visual,details,seedDrawing);
    }

    /** Internal visual events only. Never resolves files, brush work or a public stroke request. */
    public static void applyPreparedStroke(JSONObject document,JSONObject event)throws Exception {
        SketchDocument.fields(event,"type,objectId,strokeId,beforePaint,afterPaint,stroke");
        if(!event.has("beforePaint")||!event.has("afterPaint")||!event.has("stroke"))throw SketchDocument.bad("Paint strokes require native worker preparation");
        String objectId=SketchDocument.id(event,"objectId"),strokeId=SketchDocument.id(event,"strokeId");JSONObject object=SketchDocument.object(document,objectId);if(!"paint".equals(object.getString("kind")))throw SketchDocument.bad("Paint stroke requires a paint cel");SketchEditOps.requireUnlocked(SketchDocument.owner(document,objectId));
        JSONObject before=event.getJSONObject("beforePaint"),after=event.getJSONObject("afterPaint"),record=event.getJSONObject("stroke");SketchPaintStore.validateDescriptor(before);SketchPaintStore.validateDescriptor(after);
        if(!SketchDocument.canonical(before).equals(SketchDocument.canonical(object.getJSONObject("paint"))))throw new IllegalStateException("SKETCH_PAINT_SNAPSHOT_CONFLICT: prepared pixels belong to another snapshot");
        if(after.getInt("width")!=document.getInt("width")||after.getInt("height")!=document.getInt("height"))throw SketchDocument.bad("Prepared paint dimensions must match the canvas");
        if(!"videostudio.sketch.paint.stroke.v1".equals(record.optString("schema"))||!objectId.equals(record.optString("objectId"))||!strokeId.equals(record.optString("strokeId"))||!SketchDocument.canonical(before).equals(SketchDocument.canonical(record.getJSONObject("beforePaint"))))throw SketchDocument.bad("Prepared paint journal identity changed");
        object.put("paint",SketchDocument.copy(after));
    }

    public static JSONObject query(Context context,SketchProjectStore sketches,String action,JSONObject args)throws Exception {
        String id=SketchDocument.id(args,"sketchId");JSONObject document=sketches.get(id);SketchProjectStore.requireRevision(document,SketchDocument.integer(args,"expectedRevision",1,Long.MAX_VALUE-1));
        JSONObject result=new JSONObject().put("sketchId",id).put("revision",document.getLong("revision")).put("documentSha256",SketchDocument.sha256(SketchDocument.canonical(document).getBytes(StandardCharsets.UTF_8)));
        if("sketch_paint_journal".equals(action)){
            SketchDocument.fields(args,"sketchId,expectedRevision,objectId,offset,limit");String objectId=SketchDocument.id(args,"objectId");JSONObject object=SketchDocument.object(document,objectId);if(!"paint".equals(object.getString("kind")))throw SketchDocument.bad("A paint journal requires a paint cel");
            int offset=args.has("offset")?(int)SketchDocument.integer(args,"offset",0,8192):0,limit=args.has("limit")?(int)SketchDocument.integer(args,"limit",1,128):32;JSONObject descriptor=object.getJSONObject("paint");
            try(SketchPaintStore assets=new SketchPaintStore(context,id)){
                JSONArray records=assets.journal(descriptor,offset,limit),page=new JSONArray();int bytes=0;
                for(int i=0;i<records.length();i++){JSONObject record=records.getJSONObject(i);int size=record.toString().getBytes(StandardCharsets.UTF_8).length;if(size>480*1024)throw new IllegalStateException("SKETCH_PAINT_JOURNAL_BUDGET: stroke exceeds query budget");if(bytes+size>480*1024&&page.length()>0)break;page.put(record);bytes+=size;}
                int next=offset+page.length();boolean more=page.length()<records.length()||next<8192&&assets.journal(descriptor,next,1).length()>0;
                return result.put("objectId",objectId).put("snapshotSha256",descriptor.getString("sha256")).put("strokes",page).put("offset",offset).put("nextOffset",next).put("moreStrokes",more);
            }
        }
        if(!"sketch_sample_color".equals(action))throw SketchDocument.bad("Unsupported paint query");
        SketchDocument.fields(args,"sketchId,expectedRevision,frameIndex,x,y,source,objectId,sha256");double x=SketchDocument.number(args,"x",0,1),y=SketchDocument.number(args,"y",0,1);int frame=args.has("frameIndex")?(int)SketchDocument.integer(args,"frameIndex",0,document.getInt("frameCount")-1):0;String source=args.getString("source"),color;
        if("paint".equals(source)){
            if(args.has("sha256"))throw SketchDocument.bad("Paint sampling uses the current revision-bound snapshot");String objectId=SketchDocument.id(args,"objectId");JSONObject object=SketchDocument.object(document,objectId);if(!"paint".equals(object.getString("kind")))throw SketchDocument.bad("Paint sampling requires a paint cel");JSONObject descriptor=object.getJSONObject("paint");try(SketchPaintStore assets=new SketchPaintStore(context,id)){color=assets.sample(descriptor,x,y);}result.put("objectId",objectId).put("sourceSha256",descriptor.getString("sha256")).put("coordinateSpace","paint-local-normalized");
        }else if("reference".equals(source)){
            String objectId=SketchDocument.id(args,"objectId"),hash=args.getString("sha256");if(!hash.matches("[a-f0-9]{64}"))throw SketchDocument.bad("Reference sample requires its owned PNG hash");try(SketchPaintStore assets=new SketchPaintStore(context,id)){color=assets.sampleReference(document,objectId,hash,x,y,frame);}result.put("objectId",objectId).put("sourceSha256",hash).put("coordinateSpace","canvas-normalized");
        }else if("composite".equals(source)){
            if(args.has("objectId")||args.has("sha256"))throw SketchDocument.bad("Composite sampling does not take an object or reference pin");
            int pixelX=Math.min(document.getInt("width")-1,(int)Math.floor(x*document.getInt("width"))),pixelY=Math.min(document.getInt("height")-1,(int)Math.floor(y*document.getInt("height")));Bitmap pixel=Bitmap.createBitmap(1,1,Bitmap.Config.ARGB_8888);
            try(SketchFrameRenderer renderer=new SketchFrameRenderer(context,document)){Canvas canvas=new Canvas(pixel);canvas.translate(-pixelX,-pixelY);renderer.draw(canvas,frame,true);color=String.format(java.util.Locale.ROOT,"#%08X",pixel.getPixel(0,0));}finally{pixel.recycle();}
            result.put("pixelX",pixelX).put("pixelY",pixelY).put("coordinateSpace","canvas-normalized");
        }else throw SketchDocument.bad("Choose paint, reference or composite color sampling");
        return result.put("source",source).put("color",color).put("x",x).put("y",y).put("frameIndex",frame);
    }
}
